input.command:
multica issue list --output json --limit 200 2>/dev/null | python3 -c "
import json, sys
data = json.load(sys.stdin)
issues = data['issues']

pl = [i for i in issues if 'EVAL-19-playlists' in i.get('title','') or 'playlist' in i.get('title','').lower()]
by_status = {}
for i in pl:
    by_status.setdefault(i['status'], []).append(i)
for s, lst in sorted(by_status.items()):
    print(f'\n--- {s} ({len(lst)}) ---')
    for i in sorted(lst, key=lambda x: -x['number']):
        print(f\"  {i['identifier']} #{i['number']}  parent={i['parent_issue_id'] or '-'}  {i['title'][:60]}\")
"

